package io.invenlio.catalog;
import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service class CatalogInventoryAdapter implements CatalogInventoryLookup{private final VariantRepository variants;CatalogInventoryAdapter(VariantRepository variants){this.variants=variants;}@Transactional(readOnly=true)public Optional<InventoryVariant>findInventoryVariant(UUID tenantId,UUID variantId){return variants.findByIdAndTenantId(variantId,tenantId).map(v->new InventoryVariant(v.id(),v.status().name(),v.sku(),v.label()==null?v.sku():v.label(),v.unit(),Set.of("EA","BX","PK","PF").contains(v.unit()),v.trackingMode(),v.expirationRequired()));}}
